use [AdventureWorks2019]

/*** 

--create a function to that returns the top three sales generated by a salesperson, 
--as those sales appear in the Sales.SalesOrderHeader table in the AdventureWorks database

--- https://www.red-gate.com/simple-talk/databases/sql-server/t-sql-programming-sql-server/sql-server-apply-basics/
---https://www.mssqltips.com/sqlservertip/1958/sql-server-cross-apply-and-outer-apply/ 

GO
IF OBJECT_ID (N'fn_sales', N'IF') IS NOT NULL
  DROP FUNCTION dbo.fn_sales
GO
CREATE FUNCTION fn_sales (@SalesPersonID int)
RETURNS TABLE
AS
RETURN
(
  SELECT TOP 3 
    SalesPersonID, 
    ROUND(TotalDue, 2) AS SalesAmount
  FROM 
    Sales.SalesOrderHeader
  WHERE 
    SalesPersonID = @SalesPersonID
  ORDER BY 
    TotalDue DESC
)
GO

--- test it out for salesperson id 285
--SELECT SalesAmount FROM fn_sales(285)


***/


--select * from Sales.SalesOrderHeader

select top 3 SalesPersonID, round(totalDue,2) from Sales.SalesOrderHeader
--where SalesPersonID is not null
--order by SalesPersonID, TotalDue
where SalesPersonID = 285
order by TotalDue desc


SELECT 
  sp.FirstName + ' ' + sp.LastName AS FullName,
  fn.SalesAmount
FROM
  Sales.vSalesPerson AS sp
CROSS APPLY
  fn_sales(sp.BusinessEntityID) AS fn
ORDER BY
  sp.LastName, fn.SalesAmount DESC

 -- SELECT  * FROM    Sales.vSalesPerson 


 /*** Using Cross Apply with CTE - first create a function called dbo.fn_products
 IF OBJECT_ID (N'fn_products', N'IF') IS NOT NULL
  DROP FUNCTION dbo.fn_products
GO
CREATE FUNCTION fn_products (@ProductID int)
RETURNS TABLE
AS
RETURN
(
  SELECT
    p.Name AS ProductName,
    pm.Name AS ProductModel
  FROM
    Production.Product AS p
    LEFT OUTER JOIN Production.ProductModel AS pm
      ON p.ProductModelID = pm.ProductModelID
  WHERE
    p.ProductID = @ProductID
)

GO

SELECT ProductName, ProductModel 
FROM fn_products(707)

**/

-- first define CTE ProductSales. CTE then used in main SELECT statement with fn_products function. 
-- Use CROSS APPLY operator in the FROM clause to join the CTE to the function
WITH   ProductSales (ProductID, TotalSales)    AS
  (SELECT  ProductID, SUM(LineTotal)
    FROM Sales.SalesOrderDetail
    GROUP BY ProductID )
SELECT ps.ProductID,   ps.TotalSales,  fn.ProductModel
FROM   ProductSales AS ps
CROSS APPLY  fn_products(ps.ProductID) AS fn
ORDER BY   ps.ProductID

/*** USE OUTER APPLY Operator
IF OBJECT_ID (N'fn_inventory', N'IF') IS NOT NULL
  DROP FUNCTION dbo.fn_inventory
GO
CREATE FUNCTION fn_inventory (@ProductID int)
RETURNS TABLE
AS
RETURN
(
  SELECT
    ProductID,
    LocationID,
    Quantity
  FROM
    Production.ProductInventory
  WHERE
    ProductID = @ProductID
)
GO

SELECT LocationID, Quantity
FROM fn_inventory(915)
**/

SELECT
  p.ProductID,  p.Name,  fn.Quantity
FROM  Production.Product AS p   
CROSS APPLY  fn_inventory(p.ProductID) AS fn  
ORDER BY p.ProductID

SELECT  p.ProductID,  p.Name,  fn.Quantity
FROM  Production.Product AS p  
OUTER APPLY   fn_inventory(p.ProductID) AS fn
ORDER BY p.ProductID


